# Look for FL18 manifest, verify_tcb.py, and related files
for root, dirs, files in os.walk(vps_dir):
    for f in files:
        if any(keyword in f.lower() for keyword in ['fl18', 'manifest', 'verify_tcb', 'tcb', 'stdlib']):
            print(os.path.join(root, f))
    # Don't recurse too deep
    depth = root[len(vps_dir):].count(os.sep)
    if depth >= 3:
        dirs.clear()

